<template>
  <main class="video-editor">
    <header class="editor-header"><div class="project-title"><router-link to="/?media=video">← 图库</router-link><strong>{{project?.name||'视频工作台'}}</strong><span>v{{revision}} · 24 fps</span></div><div class="header-actions"><span class="save-state">{{busy?'正在提交…':lease?'已自动保存':'只读查看'}}</span><button v-if="!lease" :disabled="busy" @click="acquire">获取编辑权</button><template v-else><button :disabled="busy" @click="handoffOpen=true">交接编辑权</button><button :disabled="busy" @click="release">释放</button></template><button class="accent" :disabled="!lease||busy" @click="exportVideo">导出 MP4</button></div></header>
    <router-link class="hypit-engine-entry" :to="`/video/hypit/${id}`">打开完整 Hypit 工程 → 源文件、语义组件、评论与产物</router-link>
    <a-alert v-if="error" :message="error" type="error" show-icon closable @close="error=''"/>
    <a-spin :spinning="loading">
    <div v-if="state" class="editor-body" :class="{'studio-mode':previewMode==='hypit'}">
      <aside class="asset-panel"><div class="panel-heading">项目素材 <span>{{assets.length}}</span></div><button class="wide" :disabled="uploading" @click="fileInput?.click()">{{uploading?'正在处理并保存…':'+ 上传视频 / 图片 / 音频'}}</button><input ref="fileInput" type="file" accept="video/*,image/*,audio/*" multiple hidden @change="uploadAssets"/><div class="import-row"><input v-model="pictureId" placeholder="图库图片 ID"/><button @click="importImage">导入</button></div><div class="asset-list"><div v-for="asset in assets" :key="asset.id" class="asset" @pointerdown="beginAssetDrag($event,asset.id)" @dblclick="insertAsset(asset)"><img draggable="false" v-if="asset.posterKey" :src="assetMedia(id,asset.id,'poster')" :alt="asset.name"/><div v-else class="audio-symbol">♫</div><div><strong>{{asset.name}}</strong><small>{{asset.kind==='image'?'图像':frameTime(asset.frames)}} · {{asset.kind}}</small></div><button title="插入素材" :disabled="!lease||busy" @click="insertAsset(asset)">+</button></div></div><details class="model-panel"><summary>生成素材</summary><select v-model="modelTool"><option value="generate_image">Qwen 图像生成 / 编辑</option><option value="generate_video">LTX 视频生成</option><option value="synthesize_speech">IndexTTS 配音</option></select><textarea v-model="modelPrompt" :placeholder="modelTool==='synthesize_speech'?'输入配音文本':'描述想要生成的素材'"/><select v-if="modelTool==='synthesize_speech'" v-model="voiceName"><option v-for="voice in voiceOptions" :key="voice" :value="voice">{{voice}}</option></select><select v-model="referenceAssetId"><option value="">无参考素材</option><option v-for="asset in assets.filter(a=>modelTool==='synthesize_speech'?a.hasAudio:a.kind==='image')" :key="asset.id" :value="asset.id">参考：{{asset.name}}</option></select><button :disabled="!lease||!modelPrompt.trim()" @click="generate">生成到素材库</button></details></aside>
      <section class="central-panel"><div class="preview-heading"><div class="preview-tabs"><button :class="{active:previewMode==='live'}" @click="previewMode='live'">剪辑预览</button><button :class="{active:previewMode==='hypit'}" @click="previewMode='hypit'">Hypit Studio</button></div><select aria-label="输出画幅" :value="state.width>state.height?'landscape':'portrait'" :disabled="!lease||busy" @change="changeAspect"><option value="landscape">横屏 1280 × 720</option><option value="portrait">竖屏 720 × 1280</option></select></div><div class="preview-stage" :class="{'studio-stage':previewMode==='hypit'}"><VideoPreview v-if="previewMode==='live'" :state="state" :project-id="id" :frame="playhead" :playing="playing"/><iframe v-else :key="studioKey" ref="studioFrame" :src="`${videoBase}/projects/${id}/studio/`" title="Hypit Studio" @load="studioLoaded"/></div><div class="transport"><button @click="playing=!playing">{{playing?'暂停':'播放'}}</button><input type="range" aria-label="播放头" min="0" :max="duration" v-model.number="playhead" @input="playing=false"/><span>{{frameTime(playhead)}} / {{frameTime(duration)}} · {{playhead}}f</span></div>
      <div class="timeline-toolbar"><div><button :disabled="!lease||!undo.length||busy" @click="undoEdit">撤销</button><button :disabled="!lease||!redo.length||busy" @click="redoEdit">重做</button><button :disabled="!lease||!selected||busy" @click="split">分割</button><button :disabled="!lease||!selected||busy" @click="operate([{type:'duplicate_clip',clipId:selected!.id}])">复制</button><button :disabled="!lease||!selected||busy" @click="operate([{type:'delete_clip',clipId:selected!.id}])">删除</button><button :disabled="!lease||busy" @click="addTitle">+ 文字</button></div><div><select v-model="trackKind"><option value="visual">画面轨</option><option value="audio">音频轨</option><option value="text">文字轨</option></select><button :disabled="!lease||busy" @click="operate([{type:'add_track',kind:trackKind,name:trackKind==='visual'?'画面':trackKind==='audio'?'音频':'文字'}])">+ 轨道</button><input type="range" aria-label="时间线缩放" min="1" max="8" step=".5" v-model.number="zoom"/></div></div>
      <div class="timeline-scroll" ref="timelineElement"><div class="timeline-inner" :style="{width:`${Math.max(700,duration*zoom+180)}px`}"><div class="ruler"><span class="ruler-label">时间 / 秒</span><div class="ruler-line" @click="seekFromRuler"><span v-for="second in Math.ceil(duration/24)" :key="second" :style="{left:`${(second-1)*24*zoom}px`}">{{second-1}}</span></div></div><div v-for="(track,index) in state.tracks" :key="track.id" class="track" :style="{height:`${clipRows.heights.get(track.id)||44}px`}"><div class="track-label"><strong>{{track.name}}</strong><div><button :disabled="!lease||busy||index===0" @click="operate([{type:'reorder_track',trackId:track.id,index:index-1}])">↑</button><button :disabled="!lease||busy||index===state.tracks.length-1" @click="operate([{type:'reorder_track',trackId:track.id,index:index+1}])">↓</button></div></div><div class="track-lane" :data-track="track.id" @dragover.prevent @drop="dropAsset($event,track.id)" @click.self="seekFromRuler"><div v-for="clip in state.clips.filter(c=>c.trackId===track.id)" :key="clip.id" class="timeline-clip" role="button" tabindex="0" :aria-label="`${clip.text||clip.name}，${clip.at}帧开始，${clip.length}帧`" @keydown.enter.prevent.stop="select(clip)" @keydown.space.prevent.stop="select(clip)" :class="[clip.kind,{selected:clip.id===selectedId,muted:clip.muted}]" :style="clipStyle(clip)" @pointerdown="beginDrag($event,clip,'move')" @click.stop="select(clip)"><span class="trim-handle start" @pointerdown.stop="beginDrag($event,clip,'left')"/><span class="clip-name">{{clip.text||clip.name}} {{clip.link?'⌁':''}}</span><span class="trim-handle end" @pointerdown.stop="beginDrag($event,clip,'right')"/></div><div class="playhead" :style="{left:`${playhead*zoom}px`}"/></div></div></div></div>
      </section>
      <aside class="inspector-panel"><div class="panel-heading">片段属性</div><template v-if="selected&&draft"><div class="selected-name">{{selected.name}}</div><label>轨道<select v-model="draft.trackId" :disabled="!lease||busy"><option v-for="track in state.tracks.filter(t=>t.kind===(selected!.kind==='audio'?'audio':selected!.kind==='text'?'text':'visual'))" :key="track.id" :value="track.id">{{track.name}}</option></select></label><div class="fields-two"><label>开始 / 帧<input v-model.number="draft.at" type="number" min="0"/></label><label>长度 / 帧<input v-model.number="draft.length" type="number" min="1"/></label></div><small>素材入点 {{selected.in}}f · {{frameTime(selected.length)}}</small><template v-if="selected.kind==='text'"><label>文字<textarea v-model="draft.text"/></label><div class="fields-two"><label>字号<input type="number" v-model.number="draft.fontSize" min="8" max="300"/></label><label>颜色<input type="color" v-model="draft.color"/></label></div><small v-if="selected.precision">字幕精度：{{selected.precision==='character'?'字级对齐':'句级范围'}}</small></template><template v-if="selected.kind!=='audio'"><div class="fields-two"><label>横向位置<input v-model.number="draft.x" type="number"/></label><label>纵向位置<input v-model.number="draft.y" type="number"/></label></div><label v-if="selected.kind!=='text'">缩放<input v-model.number="draft.scale" type="number" min=".05" max="10" step=".05"/></label><label v-if="selected.kind!=='text'">画幅适配<select v-model="draft.fit"><option value="contain">完整显示</option><option value="cover">填满画幅</option><option value="stretch">拉伸</option></select></label></template><template v-if="hasAudioControls"><label>音量<input v-model.number="draft.volume" type="range" min="0" max="4" step=".05"/></label><label class="checkbox"><input type="checkbox" v-model="draft.muted"/>静音</label><div class="fields-two"><label>淡入 / 帧<input type="number" min="0" v-model.number="draft.fadeIn"/></label><label>淡出 / 帧<input type="number" min="0" v-model.number="draft.fadeOut"/></label></div></template><button class="wide accent" :disabled="!lease||busy" @click="applyProperties">应用属性</button><button v-if="canUnlink" :disabled="!lease||busy" @click="operate([{type:'unlink_clip',clipId:selected.id}])">{{selected.kind==='text'?'解除字幕关联':'解除音画联动'}}</button><button v-if="hasAudioControls" :disabled="!lease||busy" @click="transcribe">生成中文字幕</button></template><p v-else class="empty-inspector">选择一个片段，调整画面、文字或音频。</p><div class="version-panel"><details @toggle="loadVersions"><summary>历史版本</summary><div v-for="version in versions" :key="version.revision" class="version-row"><span>v{{version.revision}} {{version.message}}</span><button :disabled="!lease||busy||version.revision===revision" @click="restore(version.revision)">恢复</button></div></details></div></aside>
      <aside class="agent-panel"><div class="panel-heading">剪辑 Agent <span>{{plannerModel}}</span></div><div class="messages"><p class="agent-intro">告诉我想保留的区间、素材顺序或字幕要求。生成的素材会先保存到项目素材库。</p><div v-for="(entry,index) in chat" :key="index" :class="['chat-entry',entry.role]">{{entry.text}}</div></div><div v-if="activeRun" class="run-card"><select aria-label="任务历史" :value="activeRun.id" @change="selectRun"><option v-for="run in runs" :key="run.id" :value="run.id">{{run.kind}} · v{{run.revision}} · {{runLabel(run.status)}}</option></select><strong>{{runLabel(activeRun.status)}}</strong><span>{{activeRun.kind}} · v{{activeRun.revision}}</span><p v-if="activeRun.error">{{activeRun.error}}</p><div><button v-if="['queued','running'].includes(activeRun.status)" :disabled="!lease||busy" @click="cancelRun">取消后续步骤</button><button v-if="['error','unknown','lost','awaiting_authorization'].includes(activeRun.status)" :disabled="!lease||busy" @click="retryRun(false)">{{['unknown','lost'].includes(activeRun.status)?'明确重新生成':'重试 / 恢复'}}</button><button v-if="['error','awaiting_authorization'].includes(activeRun.status) && activeRun.kind==='agent'" :disabled="!lease||busy" @click="retryRun(true)">重新规划</button><button v-if="activeRun.status==='error' && ['generation','export','transcription'].includes(activeRun.kind)" :disabled="!lease||busy" @click="retryRun(true)">{{activeRun.kind==='export'?'创建新渲染任务':activeRun.kind==='transcription'?'重新转写':'创建新生成任务'}}</button><button v-if="exportResult" class="accent" @click="saveOpen=true">保存到图库</button><a v-if="exportResult" :href="`${videoBase}/runs/${activeRun.id}/media?download=1`">下载 MP4</a></div></div><div class="agent-input"><textarea v-model="prompt" placeholder="例如：保留第一段前3秒，接第二段，加标题，降低音乐音量" @keydown.ctrl.enter.prevent="sendMessage"/><button class="accent" :disabled="!lease||!prompt.trim()" @click="sendMessage">发送编辑请求</button></div></aside>
    </div></a-spin>
    <a-modal v-model:open="handoffOpen" title="交接编辑权" :confirm-loading="busy" @ok="handoff"><a-input v-model:value="targetId" placeholder="接收成员的用户 ID"/><p>交接后当前会话立即变为只读，接收成员有 60 秒获取编辑权。</p></a-modal>
    <a-modal v-model:open="saveOpen" title="保存成片到图库" @ok="saveVideo"><a-input v-model:value="saveName" placeholder="视频名称"/><p>保存的是导出时固定的 v{{exportResult?.revision}}。项目源文件和素材会继续保留。</p></a-modal>
  </main>
</template>
<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {message} from 'ant-design-vue';import VideoPreview from '@/components/video/VideoPreview.vue';import {videoApi,videoBase,assetMedia,frameTime,type VideoState,type VideoAsset,type VideoClip} from '@/api/videoEditor'
import {restoreHistory} from '@/utils/videoHistory'
import {timelineRows} from '@/utils/videoTimeline'
import {CollaborationGate,leaseFromProject,invalidatesEditing} from '@/utils/videoCollaboration'
const collaboration=new CollaborationGate()
const route=useRoute(),router=useRouter(),id=String(route.params.id),sessionId=crypto.randomUUID(),project=ref<any>(),state=ref<VideoState>(),revision=ref(1),assets=ref<VideoAsset[]>([]),lease=ref<any>(),loading=ref(true),busy=ref(false),error=ref(''),uploading=ref(false),fileInput=ref<HTMLInputElement>(),selectedId=ref(''),draft=ref<VideoClip>(),playhead=ref(0),playing=ref(false),previewMode=ref('live'),zoom=ref(2),trackKind=ref('visual'),timelineElement=ref<HTMLElement>(),studioFrame=ref<HTMLIFrameElement>(),undo=ref<number[]>([]),redo=ref<number[]>([]),versions=ref<any[]>([]),pictureId=ref(''),modelTool=ref('generate_video'),modelPrompt=ref(''),referenceAssetId=ref(''),voiceName=ref('speaker1_a_cn_16k.wav'),voiceOptions=ref(['speaker1_a_cn_16k.wav']),activeRun=ref<any>(),runs=ref<any[]>([]),chat=ref<{role:string;text:string}[]>([]),prompt=ref(''),handoffOpen=ref(false),targetId=ref(''),saveOpen=ref(false),saveName=ref('')
const studioKey=ref(0);let studioReady=false,disconnected=false
let renewal:ReturnType<typeof setInterval>|undefined,poller:ReturnType<typeof setInterval>|undefined,stream:EventSource|undefined,animation=0,playStart=0,playStartFrame=0,drag:{clip:VideoClip;mode:string;startX:number;at:number;length:number;trackId:string}|undefined
const duration=computed(()=>state.value?.clips.length?Math.max(...state.value.clips.map(c=>c.at+c.length)):24),selected=computed(()=>state.value?.clips.find(c=>c.id===selectedId.value)),exportResult=computed(()=>activeRun.value?.status==='done'?(activeRun.value.kind==='agent'?activeRun.value.result?.export:activeRun.value.kind==='export'?activeRun.value.result:null):null)
function writeContext(){if(!lease.value)throw Error('请先获取编辑权');return {expectedRevision:revision.value,sessionId,epoch:lease.value.epoch,idempotencyKey:crypto.randomUUID()}}
function fail(e:unknown){disconnected=!(e as any).status||(e as any).status>=500;error.value=(e as Error).message;if(invalidatesEditing(e)){lease.value=undefined;sendStudioContext()}}
async function load(refreshOnly=false){try{const result=await videoApi(`/projects/${id}`);if(disconnected){error.value='';disconnected=false}const previousLease=lease.value;lease.value=collaboration.reconcile(lease.value,leaseFromProject(result.project),sessionId,result.serverTime);if(previousLease&&!lease.value){undo.value=[];redo.value=[]}if(result.mode==='hypit'){await router.replace(`/video/hypit/${id}`);return}runs.value=result.runs.map((run:any)=>({...run,result:typeof run.result==='string'?JSON.parse(run.result):run.result}));const observedRun=runs.value.find(run=>run.id===activeRun.value?.id);if(observedRun&&observedRun.status!==activeRun.value?.status)void refreshActiveRun?.();if(result.revision<revision.value){sendStudioContext();return}project.value=result.project;assets.value=result.assets;if(refreshOnly&&result.revision===revision.value){sendStudioContext();return}if(refreshOnly&&lease.value){undo.value.push(revision.value);redo.value=[]}else if(refreshOnly){undo.value=[];redo.value=[]}if(refreshOnly&&result.revision>revision.value){studioReady=false;sendStudioContext();studioKey.value++}state.value=result.state;revision.value=result.revision;if(selected.value)select(selected.value);else draft.value=undefined;saveName.value ||=result.project.name;if(!activeRun.value&&result.runs.length){const run=result.runs[0];activeRun.value={...run,result:typeof run.result==='string'?JSON.parse(run.result):run.result};if(['running','queued'].includes(run.status))watchRun(run)}sendStudioContext()}catch(e){fail(e)}finally{loading.value=false}}
async function leaseAction(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){fail(e);if((e as any).status===409)await load(true)}finally{busy.value=false}}
async function acquire(){await leaseAction(async()=>{const acquired=await videoApi(`/projects/${id}/lease`,{action:'acquire',sessionId});if(collaboration.accept(acquired,acquired.serverTime)){lease.value=acquired;undo.value=[];redo.value=[]}sendStudioContext();await load()})}
async function release(){await leaseAction(async()=>{if(lease.value)await videoApi(`/projects/${id}/lease`,{action:'release',sessionId,epoch:lease.value.epoch});lease.value=undefined;undo.value=[];redo.value=[];sendStudioContext()})}
async function handoff(){await leaseAction(async()=>{if(!lease.value)throw Error('请先获取编辑权');await videoApi(`/projects/${id}/lease`,{action:'handoff',sessionId,epoch:lease.value.epoch,targetId:targetId.value});lease.value=undefined;undo.value=[];redo.value=[];handoffOpen.value=false;sendStudioContext()})}
async function operate(operations:any[],history=true){if(busy.value)return;busy.value=true;playing.value=false;error.value='';const old=revision.value;try{const result=await videoApi(`/projects/${id}/operations`,{...writeContext(),operations});studioReady=false;sendStudioContext();studioKey.value++;state.value=result.state;revision.value=result.revision;if(history){undo.value.push(old);redo.value=[]}if(selected.value)select(selected.value);else draft.value=undefined;sendStudioContext()}catch(e){fail(e);if((e as any).status===409)await load()}finally{busy.value=false}}
async function restore(target:number,history=true):Promise<boolean>{if(busy.value)return false;busy.value=true;playing.value=false;error.value='';const old=revision.value;try{const result=await videoApi(`/projects/${id}/restore`,{...writeContext(),revision:target});studioReady=false;sendStudioContext();studioKey.value++;state.value=result.state;revision.value=result.revision;if(history){undo.value.push(old);redo.value=[]}if(selected.value)select(selected.value);else draft.value=undefined;sendStudioContext();return true}catch(e){fail(e);if((e as any).status===409)await load();return false}finally{busy.value=false}}
async function undoEdit(){await restoreHistory(undo.value,redo.value,revision.value,target=>restore(target,false))}async function redoEdit(){await restoreHistory(redo.value,undo.value,revision.value,target=>restore(target,false))}
function select(clip:VideoClip){selectedId.value=clip.id;draft.value=JSON.parse(JSON.stringify(clip));if(clip.kind==='video'&&clip.link){const audio=state.value?.clips.find(c=>c.link===clip.link&&c.kind==='audio');if(audio)Object.assign(draft.value,{volume:audio.volume,muted:audio.muted,fadeIn:audio.fadeIn,fadeOut:audio.fadeOut})}}
async function applyProperties(){if(!draft.value||!selected.value)return;const c=draft.value,ops:any[]=[];if(c.length!==selected.value.length)ops.push({type:'trim_clip',clipId:c.id,at:c.at,length:c.length});else if(c.at!==selected.value.at)ops.push({type:'move_clip',clipId:c.id,at:c.at});if(c.trackId!==selected.value.trackId)ops.push({type:'move_clip',clipId:c.id,at:c.at,trackId:c.trackId});if(c.kind==='text')ops.push({type:'edit_subtitles',clipId:c.id,text:c.text,fontSize:c.fontSize,color:c.color,x:c.x,y:c.y});else if(c.kind!=='audio')ops.push({type:'set_layout',clipId:c.id,x:c.x,y:c.y,scale:c.scale,fit:c.fit});if(hasAudioControls.value)ops.push({type:'set_audio',clipId:c.id,volume:c.volume,muted:c.muted,fadeIn:c.fadeIn,fadeOut:c.fadeOut});if(ops.length)await operate(ops)}
async function uploadAssets(event:Event){const files=Array.from((event.target as HTMLInputElement).files||[]);uploading.value=true;try{for(const file of files){const form=new FormData();form.append('file',file);assets.value.push(await videoApi(`/projects/${id}/assets`,form))}}catch(e){fail(e)}finally{uploading.value=false;(event.target as HTMLInputElement).value=''}}
async function importImage(){try{assets.value.push(await videoApi(`/projects/${id}/assets/import`,{pictureId:pictureId.value}));pictureId.value=''}catch(e){fail(e)}}
const hasAudioControls=computed(()=>selected.value?.kind==='audio'||selected.value?.kind==='video'&&!!selected.value.link&&state.value!.clips.some(c=>c.kind==='audio'&&c.link===selected.value!.link))
const canUnlink=computed(()=>selected.value?.kind==='text'?!!(selected.value.link||selected.value.sourceClipId):!!selected.value?.link&&state.value!.clips.some(c=>c.kind!=='text'&&c.id!==selected.value!.id&&c.link===selected.value!.link))
const plannerModel=ref('Qwen3.8-27B-FP8')
const maxFrames=ref(2880)
function insertAsset(asset:VideoAsset,trackId?:string,at=playhead.value){const kind=asset.kind==='audio'?'audio':'visual';const track=trackId||(asset.purpose==='speech'?'voice':state.value?.tracks.find(t=>t.kind===kind)?.id);if(!track)return;const length=Math.min(asset.kind==='image'?72:asset.frames,maxFrames.value-at);if(length<1){fail(new Error('插入位置超过项目时长上限'));return}void operate([{type:'insert_clip',assetId:asset.id,trackId:track,at,length}])}
function assetDrag(event:DragEvent,assetId:string){event.dataTransfer?.setData('application/gallery-asset',assetId)}
let assetPointer:{id:string;x:number;y:number;moved:boolean}|undefined
function beginAssetDrag(event:PointerEvent,assetId:string){if(!lease.value||busy.value||event.button!==0||(event.target as HTMLElement).closest('button'))return;event.preventDefault();assetPointer={id:assetId,x:event.clientX,y:event.clientY,moved:false};window.addEventListener('pointermove',moveAssetPointer);window.addEventListener('pointerup',endAssetPointer,{once:true})}
function moveAssetPointer(event:PointerEvent){if(!assetPointer)return;if(Math.hypot(event.clientX-assetPointer.x,event.clientY-assetPointer.y)>6)assetPointer.moved=true;if(assetPointer.moved)event.preventDefault()}
function endAssetPointer(event:PointerEvent){window.removeEventListener('pointermove',moveAssetPointer);const source=assetPointer;assetPointer=undefined;if(!source?.moved)return;const lane=document.elementFromPoint(event.clientX,event.clientY)?.closest<HTMLElement>('[data-track]'),asset=assets.value.find(a=>a.id===source.id);if(lane?.dataset.track&&asset)insertAsset(asset,lane.dataset.track,Math.max(0,Math.round((event.clientX-lane.getBoundingClientRect().left)/zoom.value)))}
function dropAsset(event:DragEvent,trackId:string){const asset=assets.value.find(a=>a.id===event.dataTransfer?.getData('application/gallery-asset'));if(asset){const target=event.currentTarget as HTMLElement;insertAsset(asset,trackId,Math.max(0,Math.round((event.clientX-target.getBoundingClientRect().left)/zoom.value)))}}
const clipRows=computed(()=>timelineRows(state.value?.clips||[]))
function clipStyle(clip:VideoClip){const active=drag?.clip.id===clip.id;return {top:`${4+(clipRows.value.slots.get(clip.id)||0)*40}px`,left:`${(active?drag!.at:clip.at)*zoom.value}px`,width:`${Math.max(12,(active?drag!.length:clip.length)*zoom.value)}px`}}
const dragTick=ref(0);watch(dragTick,()=>{})
function beginDrag(event:PointerEvent,clip:VideoClip,mode:string){select(clip);if(!lease.value||busy.value||event.button!==0)return;event.preventDefault();drag={clip:JSON.parse(JSON.stringify(clip)),mode,startX:event.clientX,at:clip.at,length:clip.length,trackId:clip.trackId};window.addEventListener('pointermove',dragMove);window.addEventListener('pointerup',dragEnd,{once:true})}
function dragMove(event:PointerEvent){if(!drag)return;const delta=Math.round((event.clientX-drag.startX)/zoom.value);if(drag.mode==='move'){drag.at=Math.max(0,drag.clip.at+delta);const lane=document.elementFromPoint(event.clientX,event.clientY)?.closest<HTMLElement>('[data-track]');if(lane)drag.trackId=lane.dataset.track||drag.trackId}else if(drag.mode==='left'){const minimum=drag.clip.kind==='video'||drag.clip.kind==='audio'?-drag.clip.in:-drag.clip.at;const change=Math.max(minimum,Math.min(drag.clip.length-1,delta));drag.at=drag.clip.at+change;drag.length=drag.clip.length-change}else drag.length=Math.max(1,drag.clip.length+delta);dragTick.value++;state.value={...state.value!}}
function dragEnd(){window.removeEventListener('pointermove',dragMove);if(!drag)return;const edit=drag;drag=undefined;if(edit.at===edit.clip.at&&edit.length===edit.clip.length&&edit.trackId===edit.clip.trackId)return;void operate([edit.mode==='move'?{type:'move_clip',clipId:edit.clip.id,at:edit.at,trackId:edit.trackId}:{type:'trim_clip',clipId:edit.clip.id,at:edit.at,length:edit.length}])}
function seekFromRuler(event:MouseEvent){playing.value=false;playhead.value=Math.max(0,Math.min(duration.value,Math.round((event.clientX-(event.currentTarget as HTMLElement).getBoundingClientRect().left)/zoom.value)))}
function split(){if(selected.value)void operate([{type:'split_clip',clipId:selected.value.id,frame:playhead.value}])}
function addTitle(){void operate([{type:'insert_clip',trackId:state.value!.tracks.find(t=>t.kind==='text')!.id,at:playhead.value,length:72,text:'新标题'}])}
function changeAspect(event:Event){const portrait=(event.target as HTMLSelectElement).value==='portrait';void operate([{type:'set_layout',width:portrait?720:1280,height:portrait?1280:720}])}
async function loadVersions(){try{versions.value=await videoApi(`/projects/${id}/versions`)}catch(e){fail(e)}}
async function sendMessage(){try{const text=prompt.value;const run=await videoApi(`/projects/${id}/messages`,{...writeContext(),message:text,selection:{playhead:playhead.value,clipId:selectedId.value}});chat.value.push({role:'user',text});prompt.value='';watchRun(run)}catch(e){fail(e)}}
async function transcribe(){if(!selected.value)return;try{watchRun(await videoApi(`/projects/${id}/transcribe`,{...writeContext(),clipId:selected.value.id}))}catch(e){fail(e)}}
async function generate(){try{const args:any=modelTool.value==='synthesize_speech'?{text:modelPrompt.value,spk_name:voiceName.value}:{prompt:modelPrompt.value};if(referenceAssetId.value){if(modelTool.value==='generate_image')args.referenceAssetIds=[referenceAssetId.value];else args.referenceAssetId=referenceAssetId.value}watchRun(await videoApi(`/projects/${id}/generate`,{...writeContext(),tool:modelTool.value,args}));modelPrompt.value=''}catch(e){fail(e)}}
async function exportVideo(){try{watchRun(await videoApi(`/projects/${id}/exports`,writeContext()))}catch(e){fail(e)}}
function runLabel(status:string){return ({queued:'排队中',running:'执行中',done:'已完成',error:'执行失败',cancelled:'已取消',unknown:'提交结果未知',lost:'远端任务丢失',awaiting_authorization:'服务重启，等待恢复'} as Record<string,string>)[status]||status}
const completedRuns=new Set<string>()
let runGeneration=0,runRetry:ReturnType<typeof setTimeout>|undefined,refreshActiveRun:(()=>Promise<void>)|undefined
function watchRun(run:any){
  const generation=++runGeneration;activeRun.value=run;runs.value=[run,...runs.value.filter(item=>item.id!==run.id)];stream?.close();if(runRetry)clearTimeout(runRetry)
  const currentStream=new EventSource(`${videoBase}/runs/${run.id}/events`,{withCredentials:true});stream=currentStream
  let updating=false,settled=false,pendingUpdate=false
  const update=async()=>{
    if(settled||generation!==runGeneration)return
    if(updating){pendingUpdate=true;return}
    if(busy.value){runRetry=setTimeout(()=>void update(),300);return}
    updating=true
    try{
      const fresh=await videoApi(`/runs/${run.id}`)
      if(generation!==runGeneration)return
      if(busy.value){runRetry=setTimeout(()=>void update(),300);return}
      activeRun.value=fresh
      if(!['queued','running'].includes(fresh.status)){
        settled=true;currentStream.close()
        if(!completedRuns.has(run.id)){
          completedRuns.add(run.id)
          if(fresh.result?.applied&&fresh.result.revision>revision.value){undo.value.push(revision.value);redo.value=[]}
          if(fresh.result?.answer)chat.value.push({role:'assistant',text:fresh.result.answer})
          if(fresh.error)chat.value.push({role:'assistant',text:fresh.error})
        }
        await load()
      }
    }catch(e){fail(e);runRetry=setTimeout(()=>void update(),3000)}finally{updating=false;if(pendingUpdate){pendingUpdate=false;void update()}}
  }
  refreshActiveRun=update
  for(const type of ['done','error','unknown','lost','cancelled','awaiting_authorization'])currentStream.addEventListener(type,()=>void update())
  currentStream.addEventListener('step',async()=>{try{const next=await videoApi(`/projects/${id}/assets`);if(generation===runGeneration)assets.value=next}catch{}})
  currentStream.addEventListener('tool',(event)=>{if(generation!==runGeneration)return;try{const data=JSON.parse((event as MessageEvent).data);chat.value.push({role:'tool',text:`执行 ${data.name}`})}catch{}})
  void update()
}
function selectRun(event:Event){const run=runs.value.find(item=>item.id===(event.target as HTMLSelectElement).value);if(run)watchRun(run)}
async function cancelRun(){try{await videoApi(`/runs/${activeRun.value.id}/cancel`,writeContext());message.info('已停止后续步骤；远端推理可能继续')}catch(e){fail(e)}}
async function retryRun(fresh=false){if(busy.value)return;busy.value=true;try{watchRun(await videoApi(`/runs/${activeRun.value.id}/retry`,{...writeContext(),regenerate:fresh||['unknown','lost'].includes(activeRun.value.status)}))}catch(e){fail(e)}finally{busy.value=false}}
async function saveVideo(){try{const result=await videoApi('/videos',{...writeContext(),projectId:id,revision:exportResult.value.revision,runId:activeRun.value.id,name:saveName.value});saveOpen.value=false;message.success(result.reviewStatus===0?'视频已保存，等待审核':'视频已保存到图库')}catch(e){fail(e)}}
function sendStudioContext(){studioFrame.value?.contentWindow?.postMessage({type:'gallery-context',context:lease.value&&studioReady?writeContext():null},location.origin)}
function studioLoaded(){studioReady=true;sendStudioContext()}
function studioMessage(event:MessageEvent){if(event.origin!==location.origin||event.source!==studioFrame.value?.contentWindow)return;if(event.data?.type==='gallery-studio-ready')sendStudioContext();if(event.data?.type==='gallery-studio-error'){fail(Object.assign(new Error(event.data.message),{code:event.data.code,status:event.data.status}));void load(true)}if(event.data?.type==='gallery-studio-committed'){undo.value.push(revision.value);redo.value=[];void load()}}
watch(playing,(value)=>{cancelAnimationFrame(animation);if(value){playStart=performance.now();playStartFrame=playhead.value;const tick=(now:number)=>{const next=playStartFrame+Math.floor((now-playStart)/1000*24);if(next>=duration.value){playhead.value=duration.value-1;playing.value=false;return}playhead.value=next;animation=requestAnimationFrame(tick)};animation=requestAnimationFrame(tick)}})
onMounted(async()=>{window.addEventListener('message',studioMessage);await load();try{const capabilities=await videoApi('/capabilities');maxFrames.value=Math.floor(capabilities.limits.projectSeconds*24);plannerModel.value=capabilities.planner?.model||plannerModel.value}catch(e){fail(e)};renewal=setInterval(async()=>{if(!lease.value)return;const current=lease.value;try{const renewed=await videoApi(`/projects/${id}/lease`,{action:'renew',sessionId,epoch:current.epoch});if(lease.value===current&&collaboration.accept(renewed,renewed.serverTime))lease.value=renewed}catch(e){if(lease.value===current){fail(e);lease.value=undefined;sendStudioContext()}}},20_000);poller=setInterval(async()=>{if(!busy.value&&!drag)await load(true)},5_000);try{const result=await videoApi('/voices');const names=Array.isArray(result)?result:Array.isArray(result.voices)?result.voices:[];voiceOptions.value=names.map((v:any)=>typeof v==='string'?v:v.name).filter(Boolean);if(!voiceOptions.value.includes(voiceName.value)&&voiceOptions.value.length)voiceName.value=voiceOptions.value[0]!}catch{}})
onBeforeUnmount(()=>{if(renewal)clearInterval(renewal);if(poller)clearInterval(poller);stream?.close();runGeneration++;if(runRetry)clearTimeout(runRetry);cancelAnimationFrame(animation);window.removeEventListener('message',studioMessage);window.removeEventListener('pointermove',dragMove);window.removeEventListener('pointerup',dragEnd);window.removeEventListener('pointermove',moveAssetPointer);window.removeEventListener('pointerup',endAssetPointer);if(lease.value)void release()})
</script>
